package org.example;

import java.util.Scanner;

public class App {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

  
        System.out.print("Enter weight in grams (g): ");
        double grams = scanner.nextDouble();
        double milligrams = grams * 1000;
        System.out.println(grams + " g = " + milligrams + " mg\n");

        
        System.out.print("Enter weight in milligrams (mg): ");
        double inputMg = scanner.nextDouble();
        double convertedGrams = inputMg / 1000;
        System.out.println(inputMg + " mg = " + convertedGrams + " g");

        scanner.close();
    }
}

